+  CUdevice device;
+  CUcontext context = nullptr;
+  bool pushed = false;
+  CUresult error;
+  explicit Context(int ordinal) {
+    error = cuDeviceGet(&device, ordinal);
+    if (error == CUDA_SUCCESS)
